mod solution;use solution::tag_patch;#[test]fn contract(){assert_eq!(tag_patch("a=1,b=2;unset:a,set:b=3,set:c=4"),Some("b=3,c=4".to_string()));
assert_eq!(tag_patch(";set:x=a=b"),Some("x=a=b".to_string()));
assert_eq!(tag_patch("x=a=b;"),Some("x=a=b".to_string()));
assert_eq!(tag_patch("a=1,a=2;"),None);
assert_eq!(tag_patch("a--b=1;"),None);
assert_eq!(tag_patch("1a=1;"),None);
assert_eq!(tag_patch(";set:x--y=1"),None);
assert_eq!(tag_patch(";unset:"),None);
assert_eq!(tag_patch(";set:x=a;b"),None);}
